/*
 * Host-side linkage for the real production SHA-256 adapter, used by the
 * round-18 WarmLoad fixture.  New file; there is no prior version.
 *
 * The adapter translation unit is generated by test-sha256-stream-nova.py by
 * slicing the production corecrypto_sha2.c from its hardware marker.  Only
 * the privileged ID_AA64ISAR0_EL1 read and preemption primitives below are
 * host stubs; compression, digest state, update buffering and finalization are
 * the production code and the real scalar corecrypto sources.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <corecrypto/ccsha2.h>
#include <corecrypto/ccdigest.h>
#include <libkern/crypto/sha2.h>

void cc_clear(size_t len, void *dst) { volatile unsigned char *p = dst; while (len--) *p++ = 0; }
#define panic(...) do { fprintf(stderr, __VA_ARGS__); abort(); } while (0)

static void disable_preemption(void) {}
static void enable_preemption(void) {}
static uint64_t test_read_isar0(void) {
    /* Always report the SHA2 feature encoding 1, i.e. the hardware path. */
    return UINT64_C(0xabc00000) | (UINT64_C(1) << 12) | UINT64_C(0x7a5);
}
static void test_hardware_compress(ccdigest_state_t state, size_t nblocks, const void *data) {
    extern void native_sha256_compress_arm64(ccdigest_state_t, size_t, const void *);
    native_sha256_compress_arm64(state, nblocks, data);
}
extern const struct ccdigest_info ccsha256_ltc_di;
const struct ccdigest_info *ccsha256_di(void) { return &ccsha256_ltc_di; }

#define XNU_SOURCE_CORECRYPTO14 1
#define CRYPTO_SHA2 1
#include "adapter-warmload-nova.inc"
